import fs from 'node:fs';import assert from 'node:assert/strict';import {RemoteD1Database} from '../runner/report2-d1-adapter.mjs';
const db=new RemoteD1Database(process.env.REPORT2_D1_BRIDGE_URL,process.env.REPORT2_D1_BRIDGE_TOKEN),orig=db._request.bind(db);
db._request=async p=>{assert.equal(p.op,'all');assert.match(p.sql,/^\s*(SELECT|EXPLAIN QUERY PLAN)\b/i);assert.ok(!/\b(INSERT|DELETE|UPDATE|CREATE|DROP|ALTER)\b/i.test(p.sql));const u=db.usageSnapshot();assert.ok(u.rows_read<1800&&u.rows_written===0&&u.unknown_ops===0&&u.requests<13);return orig(p);};
const records={},read=async(name,sql,args=[])=>{try{records[name]=await db.prepare(sql).bind(...args).all();}catch(e){records[name]={error:String(e.message).slice(0,300)};}};
