await read('canonical:BR-USDT','SELECT * FROM canonical_publication_shadow WHERE publication_id=?1 LIMIT 1',['PUB:44d1adac3456611f1244747058466c2289e6c994']);
await read('old_cache_size','SELECT source,asset_key,observed_ts,expires_ts,LENGTH(CAST(payload_json AS BLOB)) AS bytes FROM report2_evidence_source_cache ORDER BY source,asset_key LIMIT 16');
