fs.writeFileSync('audit-output/exact-live-readback.json',JSON.stringify({schema:'report2-exact-live-source-read-v2',read_at:Date.now(),source_run_id:'1791238967062-1791238979498',records,usage:db.usageSnapshot(),sourceHTTP:0,MAIN:0,Telegram:0,storage_write:0},null,2));console.log(JSON.stringify({status:'READ_COMPLETE',usage:db.usageSnapshot(),sourceHTTP:0,MAIN:0,Telegram:0}));
